insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g1_health_v1'
from (values
('115.13.b.1',2,'Which body system includes the stomach and helps you digest food?','["digestive system", "skeletal system", "nervous system", "respiratory system"]'::jsonb,0,'The digestive system breaks down food.','original'),
('115.13.b.1',3,'Which body system uses bones to support your body?','["digestive system", "skeletal system", "circulatory system", "respiratory system"]'::jsonb,1,'Bones form the skeleton.','original'),
('115.13.b.1',3,'Your muscles and bones work together to help you...','["digest", "see colors", "move", "hear sounds"]'::jsonb,2,'Muscles pull bones to make movement.','original'),
('115.13.b.1',2,'The heart and blood vessels belong to which system?','["muscular system", "skeletal system", "digestive system", "circulatory system"]'::jsonb,3,'They move blood through the body.','original'),
('115.13.b.2.A',2,'Which health care professional checks your teeth?','["a dentist", "a pilot", "a mail carrier", "a baker"]'::jsonb,0,'Dentists care for teeth.','original'),
('115.13.b.2.A',2,'Which health care professional gives checkups and shots?','["a bus driver", "a doctor or nurse", "a chef", "a firefighter"]'::jsonb,1,'Doctors and nurses give checkups.','original'),
('115.13.b.2.A',3,'An eye doctor helps you with your...','["toes", "stomach", "vision", "hearing"]'::jsonb,2,'Eye doctors check eyesight.','original'),
('115.13.b.2.B',2,'Taking a bath or shower helps your body stay...','["sticky", "muddy", "dirty", "clean"]'::jsonb,3,'Bathing removes dirt and germs.','original'),
('115.13.b.2.B',2,'How often should you brush your teeth to keep them healthy?','["morning and night", "never", "only on weekends", "once a month"]'::jsonb,0,'Regular brushing prevents cavities.','original'),
('115.13.b.2.B',3,'Flossing helps clean...','["your shoes", "between your teeth", "your elbows", "your hair"]'::jsonb,1,'Floss reaches where a brush cannot.','original'),
('115.13.b.2.C',2,'Which action helps stop germs from spreading to others?','["sharing cups with friends", "sneezing into the air", "staying home when you are sick", "touching your face all day"]'::jsonb,2,'Staying home keeps germs from spreading.','original'),
('115.13.b.2.C',3,'Why do doctors recommend getting immunizations?','["they teach you math", "they make you sleep", "they make you taller", "they help your body fight certain diseases"]'::jsonb,3,'Immunizations build protection against illness.','original'),
('115.13.b.2.C',2,'Using a tissue when you sneeze helps...','["stop germs from spreading", "make germs grow", "save money", "make a mess"]'::jsonb,0,'Tissues catch germs.','original'),
('115.13.b.2.D',3,'Ticks and mosquitos are bugs that can bite and may spread...','["toys", "illness", "music", "paint"]'::jsonb,1,'Some bites can cause sickness.','original'),
('115.13.b.2.D',3,'Which clothing helps protect you from tick bites in tall grass?','["sandals only", "a swimsuit", "long pants and socks", "no clothes"]'::jsonb,2,'Covering your skin lowers bites.','original'),
('115.13.b.2.D',2,'Head lice are often spread when people...','["share a story", "sing", "wave", "share hats or hairbrushes"]'::jsonb,3,'Lice crawl from one head to another.','original'),
('115.13.b.3.A',2,'Excited, scared, and proud are examples of...','["emotions", "numbers", "shapes", "animals"]'::jsonb,0,'Emotions are feelings.','original'),
('115.13.b.3.A',2,'Your stomach feels tight before you go on stage. You may be feeling...','["hungry for pizza", "nervous", "asleep", "cold"]'::jsonb,1,'Nervousness can feel like tight muscles.','original'),
('115.13.b.3.B',3,'When you are very angry, it can be hard to...','["grow", "blink", "think clearly", "breathe air"]'::jsonb,2,'Strong emotions interrupt thinking.','original'),
('115.13.b.3.B',3,'A strong emotion can make it harder to...','["hear music", "see colors", "sleep always", "make good choices"]'::jsonb,3,'Emotions can interrupt self-management.','original'),
('115.13.b.3.C',2,'Which is a calming strategy?','["taking slow breaths", "yelling louder", "slamming a door", "kicking a chair"]'::jsonb,0,'Slow breathing relaxes the body.','original'),
('115.13.b.3.C',3,'Drawing quietly or listening to calm music can help you...','["run faster", "calm down", "forget how to read", "get angrier"]'::jsonb,1,'Quiet activities calm the mind.','original'),
('115.13.b.3.D',3,'Which shows a family working together to build a healthy relationship?','["they ignore each other", "they keep secrets that hurt", "they talk and listen to each other", "they yell all day"]'::jsonb,2,'Healthy relationships need good communication.','original'),
('115.13.b.3.D',2,'A peer is someone who is...','["a pet", "a stranger on TV", "your teacher", "about your age"]'::jsonb,3,'Peers are people your age.','original'),
('115.13.b.3.E',2,'Which action helps keep a friendship strong?','["being fair and sharing", "bragging all the time", "being rude", "never listening"]'::jsonb,0,'Fairness builds trust.','original'),
