('115.13.b.7',3,'Moving your body for at least 60 minutes a day helps kids...','["grow smaller", "forget how to rest", "get weaker", "stay healthy and strong"]'::jsonb,3,'Daily activity supports health.','original'),
('115.13.b.7',3,'Which activity counts as physical activity?','["riding a bike", "napping", "watching TV", "sitting still"]'::jsonb,0,'Biking moves your body.','original'),
('115.13.b.7',3,'Eating nutritious food and being active together help your...','["toys", "whole body", "homework", "backpack"]'::jsonb,1,'Nutrition and activity both build health.','original'),
